# 品牌视觉基因提取

**做什么**:看产品图,把这个品牌(或这个项目)的视觉规矩定下来:用什么主色、什么字体、什么背景与光线、品牌怎么露出、哪些不能碰。写成一张可复制的【品牌视觉基因卡】,后面出主图、详情图、视频都引用这张卡,不用每次重新猜。

**什么时候用**:员工说「这套图风格不统一 / 帮客户定个视觉方向 / 提取一下主色 / 后面几十张图要一个样 / 客户有 VI 怎么套」。

**不做什么、转给谁**
- 出图本身 → bohui-product-shot / bohui-detail-page(它们来引用这张卡)
- 品牌定位、选品、命名 → bohui-brand-strategy-launch
- 已经有一张没改过的基因卡 → 直接用,不重做

## 需要你给我什么
1. 产品图 1 张以上(白底正面 + 一张有包装盒或系列的更好)。
2. 主色(可选):客户或员工给了就用;没给从图里取。
3. 字体偏好(可选):衬线 / 无衬线 / 圆体 / 手写;没给按品类和市场配。
4. 目标平台 + 地区 + 画面语言(默认:跨境平台 / 美国 / 英文;国内平台 / 中国 / 中文)。
5. 客户有没有自己的 VI 手册:有就照它的,没有才提取。

## 怎么做

### 第一步:先问一句「谁的品牌」
- 客户的品牌、客户有 VI → 只做「翻译」:把 VI 里的色、字、调性翻成出图能用的卡,不新增、不改。
- 客户的品牌、没有 VI → 出一版「中性建议卡」,标注「建议方案,品牌视觉以客户确认为准」;帛卉是代工厂,视觉只证明工厂能做,不替客户做品牌。
- 帛卉自己的素材(官网、展会、通用能力图)→ 用帛卉系统卡:品牌行中文「帛卉化妆品」、英文「BIOSPHERE」,两色底 + 系统字体 + 胶囊,不另起炉灶。

### 第二步:看图取值(帛卉通用模型)
1. 主色:从包装取一个具体色,给名称 + HEX;不取黑白灰,除非包装本身就是黑白灰。
2. 辅色 1–2 个:与主色同色系或互补,给 HEX。
3. 气质词 3 个:清透 / 温润 / 冷静 / 奢华 / 自然……,从包装材质与排版判断。
4. 品类与人群:决定背景与道具往哪个方向走。

### 第三步:填卡(六项全填,漏一项不算完)
```
【品牌视觉基因卡】
品牌:虚构字标 / 客户字标(已授权)/ 帛卉 BIOSPHERE
一、色彩
  主色:名称 #HEX(用在:背景大面、字幕条、品牌植入)
  辅色:名称 #HEX(用在:点缀、图标、高光)
  中性色:#HEX(用在:正文、留白)
二、字体策略
  标题:无衬线 / 衬线 / 圆体,粗细,字距
  正文:与标题同族或系统字体
  颜色:标题用主色或深灰;正文深灰
  反白规则:深色底或主色底上一律哑光白 #FFFFFF
  排版:不斜体,标准行距,左对齐或居中二选一
三、背景策略(四项必填)
  风格定义:一句话(按地区本地化,如北欧极简 / 东南亚明亮 / 东亚柔和)
  场景关键词:5–8 个具体道具与材质
  光影:光源方向 / 硬柔 / 色温 / 有无轮廓光
  品牌植入:主色和字标怎么自然出现(色块、包装本身、道具),不生硬加 logo
四、语言 / 平台 / 地区:英文 / 跨境平台 / 美国(示例)
五、人物规范:是否用人、族裔匹配地区、只写姿态不写五官
六、禁忌:不用的颜色、不出现的元素、不写的宣称、竞品风格不模仿
```
每一项写「用在哪」,不然员工拿到卡不知道怎么用。

### 第四步:验卡
用这张卡写 3 张主图的提示词骨架(纯净棚拍 / 卖点隐喻 / 使用场景,手法各不同),看色、字、背景、植入是否都能落到提示词里;落不下去的那项回去改。卖点 → 场景映射(化妆品版)照 bohui-product-shot 的表。

### 第五步:交付与引用
卡片作为一段可复制文本给员工;之后 bohui-product-shot、bohui-detail-page、bohui-video-storyboard 的提示词开头加一行「引用基因卡:主色 #HEX / 背景 xxx / 字体 xxx」。同一项目改卡要说明改了哪项,旧图不回炉。

## 输出长这样
1. 一行判断:谁的品牌 / 有无 VI / 走哪条路
2. 【品牌视觉基因卡】六项
3. 【验卡】3 条主图提示词骨架
4. 【待客户确认】:主色、字体、品牌露出方式(客户品牌时必有此项)

## 护栏
- 客户有 VI 就照 VI,不「优化」客户的品牌色与字体(客户品牌资产不是工厂能动的,动了提案作废)。
- 客户没 VI 时只给「建议卡」并标注,不替客户拍板品牌视觉(帛卉定位是规模化代工,做了品牌代理的事就模糊了定位)。
- 帛卉自己的素材只用帛卉系统卡,品牌行中文「帛卉化妆品」、英文「BIOSPHERE」,不打其他旗号(法人全称只进法务页)。
- 主色必须是具体 HEX,不给黑白灰兜底(黑白灰一套图等于没定调)。
- 背景策略四项缺一不可,尤其光影和品牌植入(漏了下游每张图各自发挥,风格又散)。
- 不模仿对标品牌的配色与版式(被认出来就是抄袭,侵权风险落在出图方)。
- 卡里不写价格、起订量、交期,不写功效宣称(卡会被转发,越线文字等同工厂对外宣传)。
- 规格未知用 {容量} 占位,不编数。

## 出错了怎么办
| 情况 | 处理 |
|---|---|
| 包装是纯白或透明,取不出主色 | 从盖子、印刷字、彩盒取;都没有就按品类与市场给建议色并标注「建议」 |
| 客户给的主色和包装打架 | 以客户给的为准,包装色作辅色,标注给客户确认 |
| 字体偏好没给 | 功效型配无衬线、天然线配圆体或衬线、高端线配细衬线,标注「建议」 |
| 多个系列颜色不同 | 一系列一张卡,共用字体与背景策略,只换主色 |
| 图片太少、气质判断不准 | 请员工补一张包装盒或系列合照;不硬判 |
| 验卡时提示词落不下去 | 回改那一项(多为场景关键词太抽象),改具体道具 |

检索词:品牌视觉基因,基因卡,主色,HEX,辅色,字体策略,反白,背景策略,光影,品牌植入,视觉统一,一套图,VI,brand DNA,brand kit,color palette,typography,visual identity,style guide
');
