# 详情图分镜与文案

**做什么**:把一个产品拆成一段一段的 3:4 竖屏详情图,每段一个任务、一张画面、一组文案;先把分镜表和文案给员工看,过禁用词,再逐段出图。也能打包成「封面 + 内容图 + 笔记文案」的图文笔记包。

**什么时候用**:员工说「做详情页 / 详情图 / A+ 页面 / 竖屏图 / 分段讲清这个产品 / 出一套小红书图文」。

**不做什么、转给谁**
- 1:1 主图、单张场景图 → bohui-product-shot
- 只要文案不要图 → bohui-ecom-copy
- 只要白底图 → bohui-white-bg-retouch
- 功效宣称能不能写 → bohui-legal-advertising-claims、bohui-label-claims-review 说了算

## 需要你给我什么
1. 产品图 1 张以上(正面白底图必须有,它是所有段的基底;多色多件每个都给)。
2. 目标平台:Amazon A+ / Shopee / TikTok Shop / 独立站 / 小红书图文。
3. 目标市场与画面语言。
4. 可选:卖点(3–5 条)、段数(默认 6)、已确认的规格与成分、已有的检测或认证材料。
5. 不知道的规格用 {容量}、{净含量} 占位;没有材料支撑的功效不写。

## 怎么做

### 阶段一:识别报告 + 分镜表(停下确认)
先用帛卉通用模型看图出【识别报告】(品类 / 包材形态 / 主色 HEX / 卖点 3 条及来源 / 目标市场 / 参考图索引 / 待核对项),再按默认 6 段排分镜。段数多就拆、少就合,顺序保持「先总览、再痛点、再证明、最后信任」。

默认 6 段:
| 段号 | 任务 | 讲什么 |
|---|---|---|
| 1 | 价值总览 | 产品是什么、给谁、一句话定位 |
| 2 | 痛点与解决 | 用户困扰 → 这支产品怎么应对 |
| 3 | 核心成分或功效拆解 | 关键成分 2–3 个,只写有材料支撑的 |
| 4 | 使用步骤或真实场景 | 什么时候用、怎么用、用多少 |
| 5 | 质地、规格与对比 | 质地特写、{容量}、同系列对比(不对比竞品) |
| 6 | 信任信息与收尾 | 工厂能力、认证(只写真有的)、品牌字标留白 |

每段一行,视觉手法不重复,相邻段落画面节奏要变(棚拍 → 特写 → 场景 → 平铺 → 微距 → 品牌调性):
| 段号 | 任务 | 画面与视觉手法 | 主标题 | 副标题 | 文字要点 | 基底图 |
|---|---|---|---|---|---|---|
| 1 | 价值总览 | 纯净棚拍,产品居中,大留白 | 一句定位 | 给谁用 | 品类 · {容量} | 图 1 |
| 2 | 痛点与解决 | 卖点隐喻(见映射表) | 痛点一句 | 解决一句 | 2 条 | 图 1 |
| … | … | … | … | … | … | … |

卖点 → 场景映射(化妆品版):保湿→水珠涟漪 / 清爽→冰块薄荷水雾 / 修护→柔光丝绸羽毛 / 抗老→金色光晕 / 天然→植物苔藓原木 / 防晒→阳光斜射阴影 / 美白→珍珠牛奶白瓷 / 香氛→花瓣雾气暮色。

在这里停下:员工确认段落顺序、卖点、市场。

### 阶段二:文案与禁用词自检(停下确认)
1. 每段写主标题(≤8 字)、副标题(≤16 字)、文字要点(≤3 条),目标市场语言 + 中文对照。
2. 每条文字标来源:包装可见 / 员工提供 / 材料支撑 / 推断。推断的要员工确认,否则删。
3. 禁用词自检表过一遍:绝对化(第一、最、100%)、医疗化(治疗、消炎、根除、修复受损细胞)、未验证功效、前后对比、临床与专利字样、明星与权威背书、任何价格与数量数字。命中的标 ⚠️ 给替换建议(如「改善」代「消除」),越线的直接不写。
4. 在这里停下:员工确认文案。

### 阶段三:逐段出图(帛卉图片模型,图生图)
每段提示词骨架:「画面中的产品必须与参考图完全一致 + 画面与手法 + 构图 + 光线 + 风格色调 + 比例 3:4 + 文字区留白位置 + 负面词(模糊、比例失调、文字乱码、水印)」。不逐项描述产品细节、不描述标签字标。画面里默认不直接生成文字,文字区留白,文案由员工后期排上去,不出错字。每出一段立即展示;出完汇总。

### 图文笔记包(小红书 / 抖音图文)
封面 1 张(单一卖点、大留白)+ 内容图 N 张(默认 4,按分镜段 2–5)+ 笔记文案(标题 ≤20 字、正文 200–400 字、话题 5 个),文案走 bohui-ecom-copy 的口径。

## 输出长这样
1. 【识别报告】
2. 【分镜与文案表】(6 行,字段:段号 / 任务 / 画面与手法 / 主标题 / 副标题 / 文字要点 / 来源 / 基底图)
3. 【禁用词自检】:命中词 → 建议替换 / 已删除
4. 【平台提醒】:目标平台对比例、文字、模块的要求,一律「以该平台最新规则为准」,不写具体百分比
5. 图片 N 张,每张下面:段号 / 手法 / 基底图
6. 【待核对清单】:需要研发或法务确认的成分、功效、认证

## 护栏
- 只用员工给的、图片上看得见的、材料支撑的信息写卖点;看到芦荟不等于能写「消炎」(截图会被当成宣传材料,查到就是虚假宣传)。
- 功效文字没过审不写;不做前后对比、不放「临床」「专利」字样(欧美平台直接下架,进口方被罚后向工厂追偿)。
- 不写价格、起订量、交期、账期数字,统一「以书面报价为准」,口径引用知识库『工厂口径』页(详情图会被转发,数字兑现不了就是失信)。
- 画面品牌名一律虚构字标或留白,不出现真实品牌、明星、平台标识、竞品包装(侵权索赔落到出图方)。
- 有产品图必须图生图;没有产品图只能出示意图并标注「示意图,以样品实物为准」(客户拿图验收,对不上就是工厂责任)。
- 不用其他客户的产品与包装做本次素材(被认出一次就丢一个老客户)。
- 不做国内大红促销风,海外平台按目标市场审美(审核过不了要返工)。

## 出错了怎么办
| 情况 | 处理 |
|---|---|
| 没有正面白底图 | 请员工补,或先走 bohui-white-bg-retouch 出一张 |
| 卖点凑不够 6 段 | 合并段落,不硬凑、不编卖点 |
| 某段卖点无法映射画面 | 给 3 个备选手法让员工选 |
| 文案命中禁用词 | 标出来给替换,员工坚持要写的转法务专家裁决 |
| 产品还原不准 | 检查基底图,强化一致声明重出,不往提示词堆细节 |
| 生成失败 | 同提示词重试 2 次,还失败跳过该段标「待人工」,继续 |
| 员工中途换平台 | 回到阶段一重排分镜,已出的图保留 |
| 平台规则不确定 | 写「以平台最新规则为准」,不猜数字 |

