# 主图 / 详情 / 带货文案

**做什么**:把产品资料变成能直接贴上平台的文案:标题、卖点要点、描述、带货口播脚本、种草笔记。每个平台一套格式,每套出 3 个版本(理性版 / 场景版 / 情绪版),每条卖点标来源,发之前过一遍禁用词。

**什么时候用**:员工说「帮我写个标题 / 五点描述 / listing 文案 / 带货脚本 / 小红书笔记 / 这几个卖点怎么写成英文」。

**不做什么、转给谁**
- 帛卉自己的 B2B 内容(官网页面、AI 搜索可引用的内容、开发信、FAQ)→ bohui-content-geo-b2b
- 客户开发信、邮件序列 → bohui-cold-email-sequence
- 文案要配图 → bohui-detail-page(带文案一起排)
- 功效能不能写 → bohui-legal-advertising-claims、bohui-label-claims-review
- 多语言本地化(不止英文)→ bohui-multilingual-localization

## 需要你给我什么
1. 产品资料:品类、核心成分或特点、质地、适用人群、使用方法;有产品图更好(能看出包装信息)。
2. 平台:Amazon / Shopee / TikTok Shop / 小红书(可多选)。
3. 目标市场与语言(默认目标市场语言 + 中文对照)。
4. 可选:已确认的规格、检测或功效材料、品牌调性(有 bohui-brand-dna 基因卡就引用)、竞品链接(只看写法,不抄)。
5. 价格、销量、活动数字:员工给才写,不给就不出现。

## 怎么做

### 第一步:提卖点(三段法)
每条卖点按「特征 → 优势 → 利益」写满三格,并标来源:
| 特征(资料里有的) | 优势(它带来什么) | 利益(用户感受到什么) | 来源 |
|---|---|---|---|
| 含神经酰胺 | 帮助维持屏障 | 换季时脸没那么容易干痒 | 员工提供 |
| 凝露质地 | 铺展快 | 早上抹完直接上妆 | 图片可见 |
| … | … | … | 推断 → 需确认 |
来源只有四种:包装可见 / 员工提供 / 材料支撑 / 推断。推断的要员工确认,否则不进文案。挑 3–5 条,一个平台一次只讲 1 个主卖点。

### 第二步:按平台套格式
| 平台 | 结构 | 注意 |
|---|---|---|
| Amazon | 标题(品类词 + 主卖点 + 人群 + {容量})/ 五点要点(每点首词大写短语开头,一点一个利益)/ 描述(3 段:是谁用、怎么用、为什么选)/ 后台关键词 | 标题不堆关键词、不写促销词;字数限制以平台当前规则为准 |
| Shopee | 标题(品类 + 卖点 + 规格)/ 描述(要点式,前 3 行说完主卖点)/ 卖点短句 5 条 | 东南亚市场语言按站点;避免夸张符号 |
| TikTok Shop | 短标题 / 30 秒带货口播:钩子(3 秒)→ 痛点 → 主卖点演示 → 证明(质地、成分、使用)→ 行动 | 口语、短句,每句 ≤15 字;不写「最」「第一」 |
| 小红书 | 标题(≤20 字,一个钩子)/ 正文(200–400 字:场景 → 体验 → 成分 → 一个小缺点 → 谁适合)/ 话题 5 个 / 封面文案一句 | 像人说话,不像广告;不放价格 |

### 第三步:每套出 3 版
理性版(成分、质地、使用方法说清)/ 场景版(一个具体早晨或夜晚的用法)/ 情绪版(用户的感受与改变,不承诺结果)。三版主卖点相同,切入角度不同。

### 第四步:禁用词自检(交付前必过)
| 类型 | 例子 | 处理 |
|---|---|---|
| 绝对化 | 最、第一、100%、顶级、全网 | 删 |
| 医疗化 | 治疗、消炎、修复受损细胞、抗菌、祛斑(未取得相应许可) | 换安全表述:舒缓、帮助改善、水润、提亮 |
| 时效承诺 | 7 天见效、一夜变白 | 删 |
| 未验证功效 | 抗老、美白、防晒(无材料) | 无材料不写;有材料写「有助于」并注明依据 |
| 前后对比 / 临床 / 专利 | 「临床验证」「专利配方」 | 没有真实证明不写 |
| 数字 | 价格、销量、好评率、起订量 | 员工没给不写;商务条款一律「以书面报价为准」 |
| 背书 | 明星、医生、机构 | 未授权不写 |
命中的标 ⚠️ 给替换;员工坚持要写的转法务专家裁决,不直接输出。

## 输出长这样
```
【卖点表】3–5 行(特征 / 优势 / 利益 / 来源)
【Amazon】
  标题 ×3(理性 / 场景 / 情绪),目标语言 + 中文对照
  五点要点 ×1 套
  描述 ×1
  后台关键词 10–15 个
【TikTok Shop】短标题 ×3 + 30 秒口播脚本 ×1(分 5 段标秒数)
【小红书】标题 ×3 + 正文 ×1 + 话题 5 个 + 封面文案 1 句
【禁用词自检】命中 → 处理
【待确认】推断类卖点、需要材料的功效、员工要补的数字
```
员工只要一个平台就只出那个平台。

## 护栏
- 卖点只来自资料、图片、材料,看到「芦荟」不等于能写「舒缓修护」(截图会被当宣传材料,查到就是虚假宣传)。
- 不编成分、专利、奖项、检测、销量(海外平台直接下架,进口方被罚会向工厂追偿)。
- 不写价格、起订量、交期、账期,统一「以书面报价为准」,口径引用知识库『工厂口径』页(文案会被转发,数字兑现不了就失信)。
- 不用真实品牌、明星、竞品名做对比或背书,品牌名用客户授权字标或虚构字标(侵权索赔落到出文案方)。
- 不写国内平台大促腔调到海外平台;每个平台按目标市场语言习惯写,不是中文直译(审核过不了要返工)。
- 规格未知用 {容量}、{净含量} 占位,不编数。
- 帛卉对外落款只用「帛卉化妆品 / BIOSPHERE」(不打其他旗号)。

## 出错了怎么办
| 情况 | 处理 |
|---|---|
| 资料太少,卖点凑不够 3 条 | 出 1–2 条真有依据的,其余列「待补资料」,不编 |
| 员工给的卖点越线 | 标 ⚠️ 给安全版本;坚持要写转法务专家 |
| 标题超平台字数 | 按平台当前规则截,保留品类词与主卖点,标注「已按平台规则精简」 |
| 平台没在表里(独立站、其他站点) | 按「标题 + 要点 + 描述」通用结构出,标注「通用格式,平台规则请自查」 |
| 员工要小语种 | 先出英文版,再转 bohui-multilingual-localization |
| 三版看着一样 | 检查切入角度是否重复,换场景或换情绪 |

