name: bohui-product-shot
description: "帛卉市场技能·一张产品图 → 4 张场景效果图(市场部)。先看图出识别报告,再按卖点配 4 种不同视觉手法的场景,以产品图为基底逐张生成。何时用:产品图/场景图/效果图/主图/listing 图/出 4 张图/换个场景/把这张图做成电商图/图生图"
