# 一张产品图 → 4 张场景效果图

**做什么**:员工给一张化妆品产品图,助手先看懂它,再按卖点配出 4 张视觉手法各不相同的场景效果图,每张都以产品图为基底,产品外观不走样。

**什么时候用**:员工说「出几张场景图 / 做主图 / listing 图 / 把这张产品图换个场景 / 出效果图给客户看」。

**不做什么、转给谁**
- 竖屏详情图、分段讲解 → bohui-detail-page
- 只要抠图换纯白底 → bohui-white-bg-retouch
- 要照着某张爆款参考图的风格做 → bohui-style-clone
- 只想把一句话改成好提示词、不出图 → bohui-prompt-polish
- 没有产品图(只有文字描述)→ 只能出「示意图」,画面右下角标注「示意图,以样品实物为准」,不能叫产品图。

## 需要你给我什么
1. 产品图至少 1 张(白底正面最好;有几个颜色或几件套,每个都要给,不然做不出多色图)。
2. 目标市场(美国 / 欧洲 / 东南亚 / 中东 / 国内……)。没说就问一句,这是唯一会停下来问的必填项。
3. 可选:卖点(最多 3 条)、张数(默认 4)、比例(默认 1:1;竖版 3:4、9:16 也行)、指定场景或风格、画面要不要文字(默认无文字)。
4. 规格不知道就用 {容量}、{净含量} 占位,助手不会替你编。

## 怎么做

### 阶段一:识别报告(用帛卉通用模型看图)
输出下面这份报告后停一下,让员工确认卖点和市场;员工说「直接出」就不停。

```
【识别报告】
品类:面部精华 / 面霜 / 洁面 / 防晒 / 面膜 / 口红……
包材形态:玻璃滴管瓶 / 软管 / 广口罐 / 泵瓶 / 彩盒……
主色:#HEX(名称)+ 辅色:#HEX
卖点 3 条:① ② ③(来源写清:包装可见 / 员工提供 / 推断——推断的要确认)
目标市场:国家 + 画面语言
参考图索引:图 1 白底正面(⭐主款基底)/ 图 2 侧面 / 图 3 第二色……
待核对:看不出来的规格、成分、认证,列在这里,不进画面
```

### 阶段二:4 张方案表
按「卖点 → 场景」配画面,4 张手法必须不同。默认这样分:① 纯净棚拍(建立产品本身)② 卖点隐喻(把卖点画出来)③ 使用场景(目标市场的生活场景)④ 质地或成分特写。

卖点 → 场景映射(化妆品版):
| 卖点 | 画面 |
|---|---|
| 保湿 | 水珠、涟漪、清水面 |
| 清爽 | 冰块、薄荷叶、细水雾 |
| 修护 | 柔光、丝绸、羽毛 |
| 抗老 | 金色光晕、暗调高级感 |
| 天然 | 植物、苔藓、原木 |
| 防晒 | 阳光斜射、清晰的投影 |
| 美白 | 珍珠、牛奶、白瓷 |
| 香氛 | 花瓣、雾气、暮色 |

方案表(每张一行,员工看一眼就知道要出什么):
| 序号 | 视觉手法 | 对应卖点 | 场景与道具 | 构图与角度 | 光线 | 画面文字 | 基底图 |
|---|---|---|---|---|---|---|---|
| 1 | 纯净棚拍 | 产品本身 | 浅灰渐变台面 | 正面平视,产品居中 | 柔光主光 + 轮廓光 | 无 | 图 1 |
| 2 | 卖点隐喻 | 保湿 | 水面涟漪、悬浮水珠 | 微仰 30°,产品偏右 | 侧逆光透光 | 无 | 图 1 |
| 3 | 使用场景 | 目标市场日常 | 浴室台面、毛巾、晨光 | 俯拍 45° | 窗光 | 无 | 图 1 |
| 4 | 质地特写 | 清爽 / 修护 | 质地涂抹在亚克力板上 | 微距 | 顶光 | 无 | 图 2 |

多色、多件套:画面里出现几个,基底图就传几张,少传一张那一个颜色就会被模型瞎编。

### 阶段三:逐张生成(用帛卉图片模型,图生图)
每张的提示词固定这个骨架,顺序不要乱:
```
画面中的产品必须与参考图完全一致,严格保留形状、颜色、标签排版。
[场景与道具] + [构图与角度] + [光线] + [风格与色调,目标市场审美] + [比例 1:1] + [画质:商业产品摄影、85mm、浅景深]
负面词:模糊、比例失调、多余手指、文字乱码、水印、多余的瓶子
```
- 提示词里不逐项描述产品(不写「粉色瓶身、金色盖子」),产品长什么样交给基底图;不描述标签上的字标,负面词里也不写「logo」,写了反而把包装上的印刷字抹掉。
- 品牌名一律虚构字标或留白标签,不出现真实品牌、明星、平台标识、对标品牌包装。
- 画面文字默认无;要加,用目标市场语言,只写已过审的卖点。
- 每出一张立刻给员工看,附一句「第 N 张 · 手法 · 用了哪张基底图」;全部出完问一句要不要调整或追加。
- 文件名:产品名-序号-手法.png,同一任务再出不覆盖旧图,序号往后加。

## 输出长这样
1. 【识别报告】(阶段一格式)
2. 【方案表】(阶段二表格,4 行)
3. 4 张图,每张下面一行:序号 / 手法 / 卖点 / 基底图 / 有没有跳过
4. 结尾一句:待核对项(规格、宣称)和下一步建议(比如「第 3 张可以再出竖版给短视频封面」)

## 护栏
- 有产品图就必须图生图,不许拿纯文生图冒充产品图(客户拿图验收,产品对不上就是工厂的责任)。
- 不编规格数字,不编成分、认证、销量(截图会被当宣传材料转发,查到就是虚假宣传)。
- 功效文字先过 bohui-legal-advertising-claims / bohui-label-claims-review,没过审的不进画面;不做前后对比图(欧美构成虚假宣传,进口方被罚会向工厂追偿)。
- 不出现价格、起订量、交期等任何商务数字,统一「以书面报价为准」,口径引用知识库『工厂口径』页(图片里的数字会被当报价传播)。
- 不用其他客户的产品、包装、场景做本次素材(被认出一次,老客户就没了)。
- 4 张手法不许重复,不许全是「产品 + 文字」一种模式(客户一眼看出是流水线,提案就废了)。
- 人物与场景匹配目标市场,不用国内促销风(海外平台审核过不了,还要返工)。

## 出错了怎么办
| 情况 | 处理 |
|---|---|
| 图片模糊、不是产品图 | 请员工换清晰图,不硬做 |
| 品类或卖点看不出来 | 列出两三个可能,让员工选,不猜 |
| 产品变形、颜色偏 | 先查基底图是否漏传、是否模糊;强化「与参考图一致」声明重出;不往提示词里堆产品细节 |
| 画面出现乱码文字或陌生标志 | 负面词加「文字乱码、水印」,重出;仍有就裁切或换手法 |
| 生成失败或超时 | 同一提示词重试 2 次,还失败就跳过这张、标「待人工」,继续下一张 |
| 4 张看着太像 | 检查手法是否重复,换掉重复的那张再出 |
| 员工中途换市场或换产品 | 回到阶段一重出报告,已出的图留着不删 |
| 员工要「国内平台风格」 | 可以做,但换成小红书 / 抖音的审美口径,不做大红促销风 |

检索词:产品图,场景图,效果图,电商主图,listing 图,图生图,识别报告,卖点映射,视觉手法,基底图,本地化,负面词,商业产品摄影,product shot,lifestyle image,hero image,image-to-image,scene rendering,cosmetic packshot
');
INSERT OR REPLACE INTO skills (id, name, description, channel, content) VALUES ('bohui-prompt-polish', 'bohui-prompt-polish', '"帛卉市场技能·出图 / 视频提示词优化(市场部)。把员工一句中文需求扩成结构化的中英双语提示词,带参数建议和化妆品风格词表,交给帛卉图片模型或视频模型直接用。何时用:写提示词/优化提示词/prompt/这句话怎么让模型听懂/扩写需求/换个风格/改成夜景/更高级一点"', '市场部', '---
name: bohui-prompt-polish
description: "帛卉市场技能·出图 / 视频提示词优化(市场部)。把员工一句中文需求扩成结构化的中英双语提示词,带参数建议和化妆品风格词表,交给帛卉图片模型或视频模型直接用。何时用:写提示词/优化提示词/prompt/这句话怎么让模型听懂/扩写需求/换个风格/改成夜景/更高级一点"
channel: 市场部
---

# 出图 / 视频提示词优化

**做什么**:员工说一句「来张高级感的面霜图」,助手按固定公式补齐主体、场景、构图、光线、风格、比例、负面词,给出中英双语提示词、参数建议和改动说明;员工再说「改成夜景」就在上一版上改,不推倒重来。

**什么时候用**:员工要自己出图或出视频、但不知道怎么描述;或已经出过一版、想改风格、改光线、改场景。

**不做什么、转给谁**
- 要一整套产品图(识别报告 + 4 张方案 + 出图)→ bohui-product-shot
- 要 15 秒视频分镜表 → bohui-video-storyboard(分镜定了再回来细化提示词)
- 要照着参考图做 → bohui-style-clone
- 提示词里要写功效文字 → 先过 bohui-legal-advertising-claims

## 需要你给我什么
1. 一句需求(想要什么画面、给谁看、放哪个平台)。
2. 有没有产品图(有 → 图生图;没有 → 只能出示意图并标注)。
3. 图片还是视频;比例(图默认 1:1,视频默认 9:16);张数或时长(视频默认 15 秒)。
4. 可选:风格倾向(从下面词表挑一个)、目标市场、画面要不要文字(默认不要)。

## 怎么做

### 第一步:判定「怎么出」
| 员工的需求特征 | 怎么选 |
|---|---|
| 有产品图 | 图生图,提示词第一句「画面中的产品必须与参考图完全一致」,不描述产品细节、不描述标签字标 |
| 没有产品图 | 文生图,标签写「留白极简标签」或虚构字标,输出物叫「示意图」 |
| 要画面文字 | 尽量不让模型画字(易乱码),文字区留白后期加;非要画,只画 1 组短英文并用引号标出 |
| 要多张 | 每张换一种视觉手法,不复制同一条提示词改一个词 |
| 要快 | 短提示词:主体 + 场景 + 光线 + 比例,四句到位 |
| 要精 | 完整七段公式 |
| 要视频 | 先定三段结构,再写三镜头提示词 |
| 已有上一版 | 只改员工点名的那一段,其余原样保留 |

### 第二步:按公式组装
图片公式(七段,顺序固定):
1. 主体与包材材质(磨砂玻璃滴管瓶 / 哑光软管 / 亚克力广口罐……,有产品图时只写「参考图中的产品」)
2. 场景与道具(呼应卖点,见映射表)
3. 构图与镜头(产品位置、占比、平视 / 俯拍 / 微仰,85mm、浅景深)
4. 光线(柔光主光 + 轮廓光 + 白反光板 / 窗光 / 侧逆光透光)
5. 风格与色调(从风格词表取 3–5 个词)
6. 比例与画质(1:1 / 3:4 / 9:16,商业产品摄影,高清)
7. 负面词(模糊、比例失调、多余手指、文字乱码、水印、多余的瓶子;不写 logo)

视频公式(三镜头各 5 秒,每镜头写 3 件事:镜头运动 / 光线变化 / 主体动作):
- 镜头 1(0–5 秒)建立场景:缓慢推进,光从暗到亮,产品入画
- 镜头 2(5–10 秒)主体细节:环绕或平移,侧光扫过质地,滴落 / 涂抹 / 水珠
- 镜头 3(10–15 秒)收尾定格:回到正面,光稳定,产品居中定格留字幕位
每镜头只写一个动作,多动作会让画面扭曲。

卖点 → 场景映射(化妆品版):保湿→水珠涟漪 / 清爽→冰块薄荷水雾 / 修护→柔光丝绸羽毛 / 抗老→金色光晕 / 天然→植物苔藓原木 / 防晒→阳光斜射阴影 / 美白→珍珠牛奶白瓷 / 香氛→花瓣雾气暮色。

### 第三步:把抽象词换成可拍的词
「高级感」→ 磨砂材质 + 大留白 + 低饱和 + 单一柔光;「有活力」→ 高调光 + 水雾 + 明亮青绿;「温柔」→ 暖调窗光 + 亚麻布 + 浅景深。凡是「美」「好看」「氛围」这类词都要落到材质、光线、色彩、构图四样上。

### 第四步:输出四块,停下让员工确认参数
1. 优化后中文提示词(员工能看懂在说什么)
2. English Prompt(交给模型的那条)
3. 参数建议:图片模型 / 视频模型;图生图 / 文生图;比例;张数或时长;负面词
4. 改了什么:补了哪些、删了哪些、为什么

## 化妆品风格词表(挑一种,取 3–5 个词)
| 风格 | 关键词 | 适合 |
|---|---|---|
| 极简棚拍 | 浅灰渐变背景、柔光箱、大留白、高调 | 功效型精华、面霜 |
| 水感清透 | 水面涟漪、悬浮水珠、青蓝白、透光 | 补水喷雾、爽肤水、凝胶 |
| 植物自然 | 苔藓、原木、绿叶、晨光 | 草本、植萃、纯净护肤 |
| 奢华金属 | 金色边光、深色背景、镜面反射、丝绒 | 抗老、礼盒、高端线 |
| 实验室科技 | 玻璃器皿、冷白光、蓝灰调、极简线条 | 活性成分、功效型 |
| 暖调生活 | 亚麻布、木桌、窗光、咖啡杯 | 身体护理、家庭线 |
| 暮色香氛 | 花瓣、雾气、橙紫渐变、烛光 | 香水、香氛身体油 |
| 冰感清爽 | 冰块、薄荷、水雾、高对比冷光 | 男士、夏季、控油 |
| 丝绸柔光 | 丝绸褶皱、羽毛、奶油白、逆光 | 修护、敏感肌 |
| 珍珠白瓷 | 珍珠、牛奶、白瓷盘、柔白光 | 美白、提亮 |
| 阳光户外 | 斜射阳光、清晰投影、沙色、蓝天 | 防晒、旅行装 |
| 杂志编辑感 | 不对称构图、强阴影、单色背景、留白排版位 | 品牌形象、彩妆 |

## 输出长这样
```
【优化后中文】参考图中的产品,置于浅灰渐变台面,左上 45° 柔光主光加轮廓光,产品居中偏右占画面六成,85mm 浅景深,极简棚拍,低饱和,比例 1:1,商业产品摄影,画面无文字。
【English Prompt】The product from the reference image, on a light-grey gradient surface, soft key light from upper left with rim light, centered slightly right filling about 60% of frame, 85mm shallow depth of field, minimalist studio look, low saturation, 1:1, commercial beauty photography, no text.
Negative: blurry, distorted proportions, extra fingers, garbled text, watermark, extra bottles
【参数建议】帛卉图片模型 · 图生图 · 1:1 · 1 张
【改了什么】把「高级感」落成磨砂 + 留白 + 单一柔光;去掉画面文字;补了负面词。
```

## 护栏
- 有产品图不许文生图,提示词不描述产品细节与字标(产品会走样,客户按图验收对不上是工厂责任)。
- 画面里不出现真实品牌、logo、明星、平台标识、对标品牌包装,标签一律留白或虚构字标(侵权索赔落到出图方)。
- 功效文字没过审不写进提示词;不写「治疗」「消炎」「临床」;不做前后对比(海外构成虚假宣传,进口方被罚会向工厂追偿)。
- 不写价格、起订量、交期数字(截图会被当报价传播)。
- 规格未知用 {容量} 占位,不编数。
- 负面词避开会触发安全审核的词,用「比例失调」「多余手指」这类中性表述(命中就整张被拦)。
- 迭代只改点名的那段,不整条重写(员工前几轮确认过的东西一改就丢)。

## 出错了怎么办
| 情况 | 处理 |
|---|---|
| 员工需求太短看不出主体 | 问两句:什么产品、给谁看;不猜 |
| 出的图产品变形 | 查是不是文生图冒充;改图生图,删掉提示词里的产品描述 |
| 画面出现乱码文字 | 删掉所有文字要求,负面词加「文字乱码」 |
| 风格没出来 | 风格词换成更具体的材质与光线词,不堆形容词 |
| 视频画面扭曲、闪烁 | 每镜头只留一个动作,镜头运动改成「缓慢推进」或「固定机位」 |
| 员工说「改成 X」 | 只改对应段,输出时标出改的那段 |
| 员工要的宣称过不了审 | 换成安全表述(提亮 / 水润 / 舒缓)并说明原因,坚持要写转法务专家 |

