# 参考图风格复刻

**做什么**:员工给一张自家产品图和一张想模仿的爆款图,助手把爆款图拆成「风格骨架」(构图 / 视角 / 光线 / 色调 / 道具 / 排版 / 氛围),再把自家产品放进这个骨架里出图。产品外观以自家产品图为准,一根线都不改;参考图里的产品、品牌、模特脸、文案全部不要。

**什么时候用**:员工说「照着这张做 / 学它的光 / 这个构图我要 / 把我们的产品做成这种感觉」。

**不做什么、转给谁**
- 没有参考图,只想出场景图 → bohui-product-shot
- 只想抠白底 → bohui-white-bg-retouch
- 要做成竖屏详情段 → bohui-detail-page
- 参考图上的功效文字能不能照写 → bohui-legal-advertising-claims

## 需要你给我什么
1. 自家产品图 1 张以上(白底正面必须有;参考图是手持或俯拍的,再补一张对应角度的产品图)。
2. 风格参考图 1 张(想模仿的那张)。
3. 可选:出几版(默认 2 版:贴近版 + 变化版)、比例(默认跟参考图)、要不要保留参考图的文字排版位置(默认只留位置、不留内容)。
4. 图片角色分不清时助手会先问:哪张是我们的产品,哪张是参考。

## 怎么做

### 阶段一:识别 + 拆解(停下确认)
1. 用帛卉通用模型看自家产品图,出【识别报告】:品类 / 包材形态 / 主色 HEX / 卖点 3 条(注明来源)/ 目标市场 / 参考图索引 / 待核对。
2. 看参考图,出【风格拆解表】,每项写具体、可执行的描述,不写「好看」「高级」:

| 维度 | 参考图里是什么 | 套到我们产品上怎么改 |
|---|---|---|
| 构图与主体位置 | 产品占画面约几成、居中还是偏侧、留白在哪 | 保持 |
| 视角与景别 | 平视 / 俯拍 / 微仰,全景 / 特写 | 按我们的产品图角度选基底 |
| 光线 | 光源方向、硬光还是柔光、有无轮廓光与反光 | 保持 |
| 色调与背景 | 冷暖、主色、背景材质(石材 / 布料 / 渐变) | 背景色若与我们主色打架就换近似色 |
| 道具与场景 | 有哪些道具、和卖点什么关系 | 换成对应我们卖点的道具(见映射表) |
| 文字排版与留白 | 标题在哪、几组文字、字号层级 | 只留位置,内容换成我们的或留白 |
| 氛围关键词 | 3–5 个词(清透 / 暮色 / 实验室感……) | 保持 |
| 异物预检 | 参考图里的别家产品、品牌标、模特脸、认证标 | 全部剔除,替换为我们的产品或留白 |

3. 若参考图道具与我们卖点对不上,按「卖点 → 场景映射(化妆品版)」换:保湿→水珠涟漪 / 清爽→冰块薄荷水雾 / 修护→柔光丝绸羽毛 / 抗老→金色光晕 / 天然→植物苔藓原木 / 防晒→阳光斜射阴影 / 美白→珍珠牛奶白瓷 / 香氛→花瓣雾气暮色。
4. 停下:员工确认拆解表,尤其「要保留什么、换掉什么」。

### 阶段二:组提示词
- 基底 = 自家产品图(1–3 张,角度互补),参考图只用于分析,不当基底、不进成品。
- 提示词骨架:
```
画面中的产品必须与参考图中的产品完全一致,保留形状、颜色、标签排版。
[构图与主体位置] + [视角与景别] + [光线] + [色调与背景] + [道具与场景] + [文字区留白位置] + [氛围关键词] + [比例] + [商业产品摄影画质]
负面词:模糊、比例失调、多余手指、文字乱码、水印、多余的瓶子
```
- 不描述产品本身(不写「透明玻璃瓶配金色泵头」),产品交给基底图;不描述标签字标,负面词也不写 logo。
- 参考图里有人物:只写姿态和与产品的互动(手持、涂抹),不写五官、肤色、年龄、发型;人物种族匹配目标市场。
- 品牌名一律虚构字标或留白。

### 阶段三:出图 + 对照(帛卉图片模型,图生图)
1. 贴近版:骨架全照拆解表。变化版:换一处(光线方向或道具),其余不动。
2. 每张出完立刻展示,对照拆解表逐项打勾:构图 / 光线 / 色调 / 道具 / 产品还原 / 无异物。
3. 哪项不像只改那一项的描述重出,不推倒整条提示词。同一张改到第 3 次还不行,建议换参考图或补产品角度图。

## 输出长这样
1. 【识别报告】
2. 【风格拆解表】(8 行)
3. 图 2 张,每张下面:版本 / 基底图 / 对照打勾结果(哪项像、哪项不像)
4. 一句说明:这张图借了参考图的什么、换掉了什么
5. 待核对:参考图里的文字如果员工想照写,列出来交宣称审核

## 护栏
- 只借风格,不搬对方产品、品牌标、模特脸、文案、认证标(复制受保护的设计元素等于侵权,索赔直接落到出图方)。
- 参考图不进成品、不当基底、不发给客户(对方一眼认出来,提案作废还得罪人)。
- 产品外观必须以自家产品图为准,不许提示词描述产品去「美化」(客户拿图验收,和样品对不上就是工厂责任)。
- 参考图上的功效文字不照抄,过 bohui-legal-advertising-claims 才写;不做前后对比(海外构成虚假宣传,进口方被罚会向工厂追偿)。
- 不写价格、起订量、交期数字,统一「以书面报价为准」,口径引用知识库『工厂口径』页。
- 参考图若是其他客户的产品图,不做(老客户认出来就丢单)。
- 规格未知用 {容量} 占位,不编数。

## 出错了怎么办
| 情况 | 处理 |
|---|---|
| 分不清哪张是产品图哪张是参考图 | 停下问员工,不猜(白底单品多为产品图,带排版文字的多为参考图,仅作提示) |
| 参考图太杂、拆不出骨架 | 只取光线 + 色调 + 构图三项,其余按 bohui-product-shot 的默认手法补 |
| 产品变形、颜色偏 | 先删提示词里所有产品描述;再查基底图是否清晰、角度是否对上 |
| 画面里冒出别家产品或陌生标志 | 异物预检漏项,提示词加「画面只有一件产品」,负面词加「多余的瓶子」重出 |
| 风格丢了,像普通棚拍 | 回拆解表把光线、色调写具体(「左上 45° 硬光」而不是「有光」) |
| 参考图是竖版、员工要方图 | 先确认比例,构图按新比例重排主体位置 |
| 生成失败 | 同提示词重试 2 次,还失败标「待人工」 |

检索词:风格复刻,参考图,爆款图,构图迁移,布光,色调,氛围,风格骨架,图生图,基底图,异物预检,视觉一致,style transfer,reference image,composition,lighting,mood board,lookalike,cosmetic packshot
