# 15 秒产品短视频分镜

**做什么**:把一个产品变成一条 15 秒、静音也能看懂的短视频:先定创意方向,再出分镜表和三镜头提示词,员工确认预检清单后用帛卉视频模型生成。员工给一条爆款视频,也能先拆它的节奏和钩子,再套到自家产品上。

**什么时候用**:员工说「做条 15 秒视频 / 出个分镜 / 写个短视频脚本 / 这条爆款照着做一条 / 展会屏幕要循环播的产品视频」。

**不做什么、转给谁**
- 只要静态图 → bohui-product-shot
- 只要文案或口播稿不要画面 → bohui-ecom-copy
- 只想把分镜里某一镜的提示词写细 → bohui-prompt-polish
- 画面文字里的功效 → bohui-legal-advertising-claims 说了算

## 需要你给我什么
1. 产品图 1 张以上(正面白底最好;有它视频里的产品才不走样)或产品资料(品类、卖点、人群)。
2. 目标平台与比例:TikTok / 抖音 / 小红书用 9:16;网站、展会屏幕用 16:9;店铺卡位用 1:1。没说默认 9:16。
3. 可选:卖点(1–3 条,视频只讲 1 个主卖点)、风格、要不要人物、要不要口播(默认无口播只用字幕)、时长(默认 15 秒)。
4. 爆款拆解模式再加:参考视频的链接或员工口述的内容(几秒切一次、开头怎么钩人、讲了什么)。

## 怎么做

### 模式一:快速(默认)
直接出 1 版:【一句创意方向】→【分镜表】→【三镜头提示词】→【预检清单】,员工点头就生成。

### 模式二:分步(员工说「先给我几个方向」)
1. 出 3 个创意方向,每个一句话 + 开场钩子 + 主卖点 + 适合平台,三个方向的叙事类型不重复(比如:质地特写型 / 痛点场景型 / 生产实拍型)。停下让员工选 1 个。
2. 按选中的方向出分镜表。停下确认。
3. 出提示词与预检清单,确认后生成。

### 模式三:爆款拆解(员工给参考视频)
1. 先出【结构拆解表】:总时长 / 镜头数与每镜秒数 / 钩子类型 / 镜头顺序(特写 → 使用 → 结果……)/ 文案结构 / 节奏(几秒一切)/ 音效与字幕用法 / 为什么有效(一句)。
2. 只借结构、节奏、钩子类型,套上自家产品重排分镜;人物、品牌、原文案、原画面一律不用。
3. 之后同模式一。

### 15 秒固定三段
| 秒数 | 段落 | 任务 |
|---|---|---|
| 0–3 | 钩子 | 一眼抓住:质地特写 / 痛点场景 / 反差画面 / 结果前置 / 一个提问 |
| 3–10 | 卖点或使用 | 只讲 1 个主卖点,用画面演出来(见映射表),可带使用动作 |
| 10–15 | 收尾定格 | 产品回到正面居中,字幕写清「什么产品 · 什么卖点 · 找谁」 |

卖点 → 画面映射(化妆品版):保湿→水珠涟漪 / 清爽→冰块薄荷水雾 / 修护→柔光丝绸羽毛 / 抗老→金色光晕 / 天然→植物苔藓原木 / 防晒→阳光斜射阴影 / 美白→珍珠牛奶白瓷 / 香氛→花瓣雾气暮色。

钩子类型:提问式(「早上洗完脸紧绷?」)/ 反差式(干燥画面 → 水润画面,不做同一张脸的前后对比)/ 结果前置(先看质地铺开的光泽)/ 痛点场景(赶时间的早晨)/ 质地特写(滴管一滴落下)。

### 分镜表(每镜一行)
| 镜号 | 秒数 | 景别 | 画面 | 镜头运动 | 字幕文案 | 口播 | 音效 | 基底图 |
|---|---|---|---|---|---|---|---|---|
| 1 | 0–3 | 特写 | 滴管悬在瓶口,一滴精华落下,水面起涟漪 | 缓慢推进 | 「一滴,先补水」 | 无 | 水滴声 + 轻音乐起 | 图 1 |
| 2 | 3–7 | 近景 | 手背涂开,质地透光铺展 | 侧向平移 | 「清爽不黏」 | 无 | 音乐持续 | 图 1 |
| 3 | 7–10 | 中景 | 产品放回浴室台面,晨光 | 缓慢拉远 | 「早晚都能用」 | 无 | 环境音 | 图 1 |
| 4 | 10–15 | 正面 | 产品居中定格,标签留白 | 固定机位 | 「{品类} · 帛卉化妆品 · 代工咨询」 | 无 | 音乐收 | 图 1 |
15 秒 4–6 镜,每镜 2–4 秒;字幕每条 ≤12 字;字幕里不写功效越线词、不写任何数字。

### 三镜头视频提示词(交给帛卉视频模型)
按客户端的三段写法:镜头 1(0–5 秒)建立场景 / 镜头 2(5–10 秒)主体细节 / 镜头 3(10–15 秒)收尾定格;每镜头写清镜头运动、光线变化、主体动作,一镜一个动作。开头加「画面中的产品必须与参考图完全一致」,标签留白或虚构字标,画面不生成文字(字幕后期加)。负面词:抖动、闪烁、变形、多余的手、文字乱码、水印。

### 预检清单(生成前停下,员工逐项确认)
- [ ] 时长与比例对平台
- [ ] 产品图齐全、清晰(没有产品图只能出示意视频并标注)
- [ ] 字幕文案过了宣称审核,没有数字
- [ ] 画面无真实品牌、明星、平台标识、竞品包装
- [ ] 不是其他客户的产品
生成后检查:产品外观一致、动作不扭曲、每镜与分镜表对得上;不对的只重出那一镜。

## 输出长这样
1. 【创意方向】一句话 + 钩子类型 + 主卖点(分步模式给 3 个)
2. (爆款模式)【结构拆解表】
3. 【分镜表】4–6 行
4. 【三镜头提示词】中英各一份 + 负面词
5. 【预检清单】
6. 视频 1 条 + 一句说明(哪一镜可能需要重出、字幕建议放的位置)

## 护栏
- 视频只讲 1 个主卖点,15 秒讲 3 个等于一个都没讲清(采购在办公室静音看,看不懂就关)。
- 静音可懂:字幕说清产品、卖点、找谁;不靠口播和音乐(邮件和即时通讯里默认静音播放)。
- 字幕不写价格、起订量、交期、出样周期,统一「以书面报价为准」,口径引用知识库『工厂口径』页(视频会被转发,数字兑现不了就失信)。
- 不做同一张脸的前后对比、不出现「临床」「治疗」「专利」字样、功效文字先过审(海外构成虚假宣传,进口方被罚会向工厂追偿)。
- 爆款拆解只借结构和节奏,不用原视频的人、画面、品牌、文案(侵权 + 平台判搬运)。
- 有产品图必须以产品图为基底,不许纯文字凭空生成产品(客户按视频验收,产品对不上是工厂责任)。
- 不用其他客户的产品做本次素材(被认出一次就丢一个老客户)。
- 规格未知用 {容量} 占位,不编数。

## 出错了怎么办
| 情况 | 处理 |
|---|---|
| 员工没给产品图 | 说明只能出示意视频,画面标注「示意」;建议先出一张白底图 |
| 卖点太多 | 让员工选 1 个主卖点,其余留给下一条视频 |
| 参考视频拆不出结构(太长或太杂) | 只拆前 15 秒的钩子与节奏,其余按固定三段补 |
| 产品在视频里变形 | 查基底图是否清晰;提示词删掉产品描述,强化一致声明;只重出那一镜 |
| 画面抖动、闪烁、手指怪 | 每镜只留一个动作,镜头运动改缓慢推进或固定机位 |
| 字幕命中禁用词 | 换安全表述,员工坚持要写转法务专家 |
| 生成失败或超时 | 同提示词重试 2 次,仍失败标「待人工」并保留分镜表 |
| 员工中途换平台 | 只改比例与字幕位置,分镜不动 |

